 Map<String,Object> view(Map<String,Object> row){var result=new LinkedHashMap<String,Object>();for(var entry:row.entrySet()){String[] pieces=entry.getKey().split("_");StringBuilder key=new StringBuilder(pieces[0]);for(int n=1;n<pieces.length;n++)key.append(Character.toUpperCase(pieces[n].charAt(0))).append(pieces[n].substring(1));Object v=entry.getValue();if(v instanceof BigDecimal decimal)v=decimal.setScale(2).toPlainString();else if(v instanceof java.time.LocalDateTime dateTime)v=dateTime.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));else if(v instanceof java.sql.Timestamp timestamp)v=timestamp.toLocalDateTime().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));else if(v instanceof java.time.LocalDate date)v=date.toString();else if(v instanceof java.sql.Date date)v=date.toLocalDate().toString();else if(entry.getKey().equals("id")||entry.getKey().endsWith("_id"))v=v==null?null:v.toString();result.put(key.toString(),v);}if(row.containsKey("order_step_id")){result.put("completedQuantityKind","WEIGHT".equals(row.get("measurement_mode"))?"REFERENCE":"ACTUAL");markBatchMapping(result,row.get("batch_id"),true);var adoption=legacyAdoption(jdbc,row);if(adoption!=null){result.put("legacyAdopted",true);result.put("mappingStatus","LEGACY_ADOPTED");result.put("targetBatchId",text(adoption.get("batchId")));result.put("targetExecutionId",adoption.get("targetExecutionId")==null?null:text(adoption.get("targetExecutionId")));result.put("writeBlockedReasonCode","LEGACY_ADOPTED");result.put("writeBlockedReason","历史加工已承接，请操作目标生产批次");}}return result;}
